def page(rows, offset, limit):
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError("offset must be a non-negative integer")
    if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 100:
        raise ValueError("limit must be an integer between 1 and 100")
    return {"items": rows[offset:offset + limit], "total": len(rows), "offset": offset, "limit": limit}


def _coerce_query_int(value):
    if isinstance(value, str):
        if not value or not value.isascii() or not value.isdigit():
            raise ValueError("query parameter must be a non-empty ASCII decimal digit string")
        return int(value)
    return value


def page_query(rows, params):
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    offset = _coerce_query_int(params.get("offset", 0))
    limit = _coerce_query_int(params.get("limit", 50))
    return page(rows, offset, limit)
